headStyles:
#header,
#footer-sections,
footer.sections,
.footer-sections,
#footer { display: none !important; }

.fe-block:has(.sqs-block-code) { height: auto !important; align-self: start; }
.page-section:has(.sqs-block-code) { min-height: 0 !important; }
.page-section:has(.sqs-block-code) .fluid-engine { grid-template-rows: auto !important; }

#uk-legal-bar {
  display: none;
  background: #2A2F3D;
  color: #ffffff;
  padding: 28px 20px;
  text-align: center;
  font-family: inherit;
  font-size: 13px;
  line-height: 1.8;
}
#uk-legal-bar .inner { max-width: 640px; margin: 0 auto; }
#uk-legal-bar .muted { opacity: 0.7; }
